const b = $input.first().json.body || $input.first().json;
return [{ json: {
  plate: String(b.plate || 'KA01AB1234').toUpperCase().replace(/[^A-Z0-9]/g,''),
  text: String(b.text || 'Your car is blocking mine'),
  lang: b.lang || 'en',
  ownerLang: b.ownerLang || 'en'
}}];

const inp = $('Normalise').first().json;
const a = (n) => { try { return $(n).first().json.answers.q; } catch (e) { return null; } };
const r = a('Jev: what is wrong?'), u = a('Jev: is it urgent?'), s = a('Jev: spam or abuse?');
const unsure = [];
let reason = 'other', conf = 0;
if (r && r.choice) { reason = r.choice; conf = r.answer_confidence ?? r.confidence; }
if (!r || conf < 0.65) unsure.push('reason');
const pU = u ? u.noul : null, pS = s ? s.noul : null;
if (pU === null || (pU > 0.35 && pU < 0.65)) unsure.push('urgency');
if (pS === null || (pS > 0.35 && pS < 0.65)) unsure.push('spam');
return [{ json: { ...inp, reason, reasonConfidence: conf, pUrgent: pU, pSpam: pS, jevUnsure: unsure,
  spam: pS !== null && pS >= 0.65,
  note: unsure.length ? 'Jev unsure about: ' + unsure.join(', ') + ' (the cheap model decides these)' : 'Jev sure on all three' } }];

const d = $('Decide (low confidence = fallback)').first().json;
let m = {};
try { m = JSON.parse($input.first().json.choices[0].message.content); } catch (e) { m = { title: d.reason, body: d.text, replies: [] }; }
return [{ json: { delivered: true,
  phone: { badge: d.pUrgent >= 0.5 ? 'URGENT' : 'normal', car: d.plate, kind: d.reason, title: m.title, body: m.body, quickReplies: m.replies },
  jev: d.note, pUrgent: d.pUrgent, reasonConfidence: d.reasonConfidence } }];
